Plan (no files written yet):

1. `src/auth/refresh.ts` — `refreshSession` via `getSession` → `undefined` if none → `revokeSession(token)` → `createSession(current.userId)` (same call shape as `login` at src/api/routes.ts:11, importing from `session.ts` directly to avoid a routes→refresh cycle). Imports use the repo's `.ts` extension + inline `type` (verbatimModuleSyntax), JSDoc one-liner like the other exports.
2. `test/refresh.test.ts` — node:test, `beforeEach(resetSessions)`, covers the happy path (same userId, new token, old token dead) and the unknown-token case. No other files touched.

`src/auth/refresh.ts`
```ts
import { createSession, getSession, revokeSession, type Session } from "./session.ts";

/** Revoke the token's session and start a fresh one for the same user, or undefined if there is none. */
export function refreshSession(token: string): Session | undefined {
  const current = getSession(token);
  if (!current) return undefined;
  revokeSession(token);
  return createSession(current.userId);
}
```

`test/refresh.test.ts`
```ts
import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { createSession, getSession, resetSessions } from "../src/auth/session.ts";
import { refreshSession } from "../src/auth/refresh.ts";

beforeEach(() => resetSessions());

test("refreshSession replaces the session with a fresh one for the same user", () => {
  const old = createSession("u_1");
  const fresh = refreshSession(old.token);
  assert.ok(fresh);
  assert.equal(fresh.userId, "u_1");
  assert.notEqual(fresh.token, old.token);
  assert.equal(getSession(old.token), undefined);
  assert.equal(getSession(fresh.token)?.userId, "u_1");
});

test("refreshSession returns undefined when the token has no live session", () => {
  assert.equal(refreshSession("nope"), undefined);
});
```

